import React from "react";
import { useNavigate, useLocation } from "react-router-dom";

function Layout({
  children,
  filter,
  setFilter,
  category,
  setCategory,
  search,
  setSearch,
}) {
  const navigate = useNavigate();
  const location = useLocation();

  const user = JSON.parse(localStorage.getItem("user") || "null");

  const handleLogout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  const isActive = (path) => location.pathname === path;

  return (
    <div className="layout">

      {/* TOP NAVBAR */}
      <header className="navbar">

        <div className="brand" onClick={() => navigate("/dashboard")}>
          <div className="logo">C</div>

          <div>
            <h3>Campus Connect</h3>
            <span>Student Learning Hub</span>
          </div>
        </div>

        {/* SEARCH */}
        <div className="search-container">
          <span className="search-icon">⌕</span>

          <input
            type="text"
            placeholder="Search questions, notes & topics..."
            value={search || ""}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {/* PROFILE */}
        <div className="navbar-profile">
          <div className="avatar">
            {user?.name?.[0]?.toUpperCase() || "U"}
          </div>

          <div className="profile-info">
            <strong>{user?.name || "User"}</strong>
            <span>{user?.role || "Student"}</span>
          </div>

          <button className="logout-top" onClick={handleLogout}>
            Logout
          </button>
        </div>

      </header>


      {/* MAIN AREA */}
      <div className="content">

        {/* SIDEBAR */}
        <aside className="sidebar">

          <div>

            <p className="menu-title">MENU</p>

            <button
              className={isActive("/dashboard") ? "side-btn active" : "side-btn"}
              onClick={() => navigate("/dashboard")}
            >
              <span>⌂</span>
              Dashboard
            </button>

            <button
              className={isActive("/profile") ? "side-btn active" : "side-btn"}
              onClick={() => navigate("/profile")}
            >
              <span>◉</span>
              Profile
            </button>

            <button
              className={isActive("/notes") ? "side-btn active" : "side-btn"}
              onClick={() => navigate("/notes")}
            >
              <span>▤</span>
              My Notes
            </button>


            <p className="menu-title filter-title">FILTERS</p>

            {filter && setFilter && (
              <div className="filter-box">
                <label>Sort by</label>

                <select
                  value={filter}
                  onChange={(e) => setFilter(e.target.value)}
                >
                  <option value="recent">Recent</option>
                  <option value="popular">Popular</option>
                </select>
              </div>
            )}

            {category && setCategory && (
              <div className="filter-box">
                <label>Category</label>

                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                >
                  <option value="all">All Categories</option>
                  <option value="notes">Notes</option>
                  <option value="projects">Projects</option>
                  <option value="guidance">Guidance</option>
                  <option value="career">Career</option>
                  <option value="skills">Skills</option>
                </select>
              </div>
            )}

          </div>


          {/* BOTTOM */}
          <div className="sidebar-bottom">

            <div className="sidebar-user">
              <div className="avatar small">
                {user?.name?.[0]?.toUpperCase() || "U"}
              </div>

              <div>
                <strong>{user?.name || "User"}</strong>
                <span>{user?.role || "Student"}</span>
              </div>
            </div>

            <button className="side-logout" onClick={handleLogout}>
              ↪ Logout
            </button>

          </div>

        </aside>


        {/* PAGE CONTENT */}
        <main className="main">
          {children}
        </main>

      </div>

    </div>
  );
}

export default Layout;
